select

from ((t_task_info t1 left join t_product t2 ON t1.product_id = t2.id) LEFT JOIN t_version t3  ON t1.version_id = t3.id)
where t1.is_delete = 0

    and t2.id = #{taskInfoEntity.productId ,jdbcType=VARCHAR}



    and t1.`name` like CONCAT('%','${taskInfoEntity.name}','%' )


    and t1.create_time >= #{taskInfoEntity.createTime ,jdbcType=DATETIMEOFFSET}


    and t1.end_time <= #{taskInfoEntity.endTime ,jdbcType=DATETIMEOFFSET}


    and t1.creator like CONCAT('%','${taskInfoEntity.creator}','%' )


    and t1.department = #{taskInfoEntity.department ,jdbcType=VARCHAR}


    and t1.developer like CONCAT('%','${taskInfoEntity.developer}','%' )


    and t1.entry_auditor  like CONCAT('%','${taskInfoEntity.entryAuditor}','%' )


    and t1.translator  like CONCAT('%','${taskInfoEntity.translator}','%' )


    and t1.translation_auditor  like CONCAT('%','${taskInfoEntity.translationAuditor}','%' )


    and t1.description = #{taskInfoEntity.description ,jdbcType=VARCHAR}


    and t1.state in( ${taskInfoEntity.state } )


    and t1.version_id = #{taskInfoEntity.versionId }


    and t1.translate_type = #{taskInfoEntity.translateType }


order by create_time desc

    LIMIT #{limit} OFFSET #{offset}

